"use client";
import { scrollAreaListChildren } from "@/components/ui/scroll-area";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-navigation-menu";
import {
  useFlowAppearance,
  useFlowGroup,
} from "@/lib/cojeev-motion/use-flow";
import { MotionPresence } from "@/components/ui/presence";
import { usePresence } from "motion/react";
import {
  createMotionLane,
  motionTokens,
  useChoreography,
} from "@/lib/cojeev-motion/choreography";
import { assignMotionRef } from "@/lib/cojeev-motion/refs";
import {
  adornItem,
  itemText,
  type ItemAdornmentItemProps,
} from "@/components/ui/item-adornment";
import { StateChevron } from "@/components/ui/animated-icon";
const NavigationValueContext = React.createContext("");
const NavigationItemContext = React.createContext("");
export const navigationMenuVariants = cva("v-nav [display:grid] [gap:2px]");
export type NavigationMenuProps = React.ComponentProps<
  typeof Primitive.Root
> & {
  /** Grouped destinations, a preview shelf, or a compact disclosure menu. */
  appearance?: "directory" | "shelf" | "compact";
};
export function NavigationMenu({
  className,
  ref,
  orientation = "vertical",
  value,
  defaultValue = "",
  onValueChange,
  appearance,
  onPointerOverCapture,
  onClickCapture,
  onKeyDownCapture,
  ...props
}: NavigationMenuProps) {
  const [localValue, setLocalValue] = React.useState(defaultValue);
  const selected = value ?? localValue;
  // Radix can still deliver a delayed hover-open after a click/Escape close.
  // Only a fresh pointer entry or explicit activation may reopen that menu.
  const dismissed = React.useRef(false);
  const flowRef = useFlowGroup<HTMLElement>(ref, {
    itemSelector: ".v-nav__item",
    activeSelector: '[aria-current="page"]',
  });
  return (
    <NavigationValueContext.Provider value={selected}>
      <Primitive.Root
        ref={flowRef}
        orientation={orientation}
        value={selected}
        onValueChange={(next) => {
          if (next && dismissed.current) return;
          if (!next) dismissed.current = true;
          if (value === undefined) setLocalValue(next);
          onValueChange?.(next);
        }}
        onPointerOverCapture={(event) => {
          onPointerOverCapture?.(event);
          if (event.defaultPrevented) return;
          const target =
            event.target instanceof Element
              ? event.target.closest('[data-slot="navigation-menu-trigger"]')
              : null;
          if (
            target &&
            !(
              event.relatedTarget instanceof Node &&
              target.contains(event.relatedTarget)
            )
          )
            dismissed.current = false;
        }}
        onClickCapture={(event) => {
          onClickCapture?.(event);
          if (!event.defaultPrevented) dismissed.current = false;
        }}
        onKeyDownCapture={(event) => {
          onKeyDownCapture?.(event);
          if (!event.defaultPrevented && event.key === "Escape")
            dismissed.current = true;
          else if (
            !event.defaultPrevented &&
            (event.key === "Enter" || event.key === " ")
          )
            dismissed.current = false;
        }}
        data-slot="navigation-menu"
        data-appearance={appearance}
        data-part="root"
        className={cn(navigationMenuVariants(), className)}
        {...props}
      />
    </NavigationValueContext.Provider>
  );
}
export type NavigationMenuListProps = React.ComponentProps<
  typeof Primitive.List
>;
export function NavigationMenuList({
  className,
  ...props
}: NavigationMenuListProps) {
  return (
    <Primitive.List
      data-slot="navigation-menu-list"
      className={cn("grid", className)}
      {...props}
    />
  );
}
export type NavigationMenuItemProps = React.ComponentProps<
  typeof Primitive.Item
>;
export function NavigationMenuItem({
  value,
  ...props
}: NavigationMenuItemProps) {
  const generated = React.useId();
  const itemValue = value ?? generated;
  return (
    <NavigationItemContext.Provider value={itemValue}>
      <Primitive.Item
        value={itemValue}
        data-slot="navigation-menu-item"
        {...props}
      />
    </NavigationItemContext.Provider>
  );
}
export type NavigationMenuLinkProps = React.ComponentProps<
  typeof Primitive.Link
> &
  ItemAdornmentItemProps;
export function NavigationMenuLink({
  className,
  children,
  adornment,
  adornmentId,
  active,
  ref,
  ...props
}: NavigationMenuLinkProps) {
  const morphRef = useMorph<HTMLAnchorElement>("nav", ref);
  return (
    <Primitive.Link
      ref={morphRef}
      data-slot="navigation-menu-link"
      data-part="item"
      active={active}
      aria-current={active ? "page" : undefined}
      className={cn("v-nav__item", className)}
      {...props}
    >
      {adornItem(
        children,
        adornment,
        adornmentId ?? props.href ?? itemText(children),
        props.asChild,
      )}
    </Primitive.Link>
  );
}
export type NavigationMenuGroupProps = React.ComponentProps<"div">;
export function NavigationMenuGroup({
  className,
  ...props
}: NavigationMenuGroupProps) {
  return (
    <div
      data-slot="navigation-menu-group"
      data-part="group"
      className={cn("v-nav__group", className)}
      {...props}
    />
  );
}
export type NavigationMenuCountProps = React.ComponentProps<"span">;
export function NavigationMenuCount({
  className,
  ref,
  ...props
}: NavigationMenuCountProps) {
  const morphRef = useMorph<HTMLSpanElement>("pills", ref);
  return (
    <span
      ref={morphRef}
      data-slot="navigation-menu-count"
      data-part="indicator"
      className={cn("v-nav__count", className)}
      {...props}
    />
  );
}
export type NavigationMenuTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
> &
  ItemAdornmentItemProps & { chevron?: boolean };
export function NavigationMenuTrigger({
  className,
  children,
  adornment,
  adornmentId,
  chevron = true,
  ...props
}: NavigationMenuTriggerProps) {
  const selected = React.useContext(NavigationValueContext);
  const itemValue = React.useContext(NavigationItemContext);
  return (
    <Primitive.Trigger
      type="button"
      data-slot="navigation-menu-trigger"
      data-part="trigger"
      className={cn("v-nav__item", className)}
      {...props}
    >
      {adornItem(
        children,
        adornment,
        adornmentId ?? itemText(children),
        props.asChild,
        chevron ? <StateChevron open={selected === itemValue} /> : null,
      )}
    </Primitive.Trigger>
  );
}
export type NavigationMenuContentProps = React.ComponentProps<
  typeof Primitive.Content
>;
export function NavigationMenuContent({
  ref,
  forceMount,
  children,
  ...props
}: NavigationMenuContentProps) {
  const selected = React.useContext(NavigationValueContext);
  const itemValue = React.useContext(NavigationItemContext);
  const open = selected === itemValue;
  const content = (
    <Primitive.Content
      ref={ref}
      forceMount
      data-state={open ? "open" : "closed"}
      data-slot="navigation-menu-content"
      data-part="content"
      {...props}
    >
      {scrollAreaListChildren(children, props.asChild)}
    </Primitive.Content>
  );
  // Radix registers viewport content through a separate mounter. Retain that
  // actual registration until the surface exits, then let Radix unregister it.
  if (forceMount) return content;
  return (
    <MotionPresence>
      {open && (
        <NavigationMenuRetainedContent key={itemValue} ref={ref} {...props}>
          {scrollAreaListChildren(children, props.asChild)}
        </NavigationMenuRetainedContent>
      )}
    </MotionPresence>
  );
}
function NavigationMenuRetainedContent({
  ref,
  ...props
}: NavigationMenuContentProps) {
  const [host, setHost] = React.useState<HTMLDivElement | null>(null);
  const [present, safeToRemove] = usePresence();
  const { quiet, transition } = useChoreography();
  const attach = React.useCallback(
    (node: HTMLDivElement | null) => {
      setHost(node);
      const release = assignMotionRef(ref, node);
      return () => {
        setHost(null);
        release();
      };
    },
    [ref],
  );
  React.useLayoutEffect(() => {
    if (!host) return;
    // The native viewport renders its registered node outside this component's
    // React subtree. Drive that actual node, and release its registration only
    // when this Motion lane completes; no elapsed-time unmount approximation.
    const lane = createMotionLane(
      Number.parseFloat(host.style.opacity || (present ? "0" : "1")),
      (value) => {
        host.style.opacity = String(Math.max(0, Math.min(1, value)));
        host.style.scale = String(0.975 + 0.025 * value);
      },
    );
    lane.jump(lane.get());
    const finish = () => {
      if (!present) safeToRemove?.();
    };
    if (quiet) lane.jump(present ? 1 : 0);
    else
      lane.to(
        present ? 1 : 0,
        present
          ? transition
          : {
              duration: motionTokens.duration.exit,
              ease: [...motionTokens.ease.exit],
            },
        finish,
      );
    return () => lane.dispose();
  }, [host, present, quiet, transition, safeToRemove]);
  // AnimatePresence records its exiting keys in a parent layout effect. Quiet
  // paint is synchronous, but removal must run after that registration commits.
  React.useEffect(() => {
    if (quiet && !present) safeToRemove?.();
  }, [quiet, present, safeToRemove]);
  return (
    <Primitive.Content
      {...props}
      ref={attach}
      forceMount
      data-slot="navigation-menu-content"
      data-part="content"
      data-state={present ? "open" : "closed"}
      data-motion-exiting={!present ? "true" : undefined}
      inert={!present || props.inert || undefined}
      aria-hidden={!present ? true : props["aria-hidden"]}
    />
  );
}
export type NavigationMenuViewportProps = React.ComponentProps<
  typeof Primitive.Viewport
>;
export function NavigationMenuViewport({
  ref,
  ...props
}: NavigationMenuViewportProps) {
  const selected = React.useContext(NavigationValueContext);
  const flowRef = useFlowAppearance<HTMLDivElement>(!!selected, ref, "fade");
  return (
    <Primitive.Viewport
      ref={flowRef}
      data-slot="navigation-menu-viewport"
      data-part="viewport"
      {...props}
    />
  );
}
export type NavigationMenuIndicatorProps = React.ComponentProps<
  typeof Primitive.Indicator
>;
export function NavigationMenuIndicator(props: NavigationMenuIndicatorProps) {
  return (
    <Primitive.Indicator
      data-slot="navigation-menu-indicator"
      data-part="indicator"
      {...props}
    />
  );
}

export type NavigationMenuLabelProps = React.ComponentProps<"span">;
export function NavigationMenuLabel({
  className,
  ...props
}: NavigationMenuLabelProps) {
  return (
    <span
      data-slot="navigation-menu-label"
      className={cn("v-nav__label", className)}
      {...props}
    />
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"][data-morph] {
  color: var(--v-text);
}
.v-nav__count:where(
  [data-slot="navigation-menu"],
  [data-slot^="navigation-menu-"]
) {
  color: var(--v-on-accent);
}
[dir="rtl"]
  .v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"]::before {
  left: auto;
  right: 0;
}
.v-nav__group:where(
  [data-slot="navigation-menu"],
  [data-slot^="navigation-menu-"]
) {
  font-size: 13px;
  color: var(--sidebar-muted);
  padding: var(--s-4) var(--s-3) var(--s-2);
}
.v-nav__item:where(
  [data-slot="navigation-menu"],
  [data-slot^="navigation-menu-"]
) {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--s-4);
  height: var(--nav-row);
  padding: 0 var(--s-3) 0 var(--s-5);
  border-radius: var(--r-md);
  color: var(--sidebar-foreground);
  font-size: var(--fs-body);
  text-decoration: none;
  transition: background var(--t-micro);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  ):hover {
  background: rgba(251, 244, 230, 0.07);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )
  .v-icon {
  width: 20px;
  height: 20px;
}
.v-nav__label:where(
  [data-slot="navigation-menu"],
  [data-slot^="navigation-menu-"]
) {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"] {
  color: var(--sidebar-primary);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"]::before {
  content: "";
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: var(--sidebar-primary);
  border-radius: 1px;
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"]::after {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--sidebar-primary);
  animation: v-breathe var(--breath) ease-in-out infinite;
}
.v-nav__count:where(
  [data-slot="navigation-menu"],
  [data-slot^="navigation-menu-"]
) {
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: var(--r-pill);
  background: var(--v-pink);
  color: var(--v-on-accent);
  font-size: 10px;
  font-weight: 700;
  display: grid;
  place-items: center;
}
.v-nav__item:where(
  [data-slot="navigation-menu"],
  [data-slot^="navigation-menu-"]
) {
  cursor: pointer;
}
:root.-doc-hidden
  .v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"]::after {
  animation-play-state: paused;
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[data-ink="light"] {
  color: var(--cream-fixed);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[data-ink="light"][aria-current="page"] {
  color: var(--v-pink);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[data-ink="dark"] {
  color: var(--v-on-accent);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[data-ink="dark"][aria-current="page"] {
  color: var(--v-brand);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"]::before {
  display: none;
}
.v-nav__item:where(
  [data-slot="navigation-menu"],
  [data-slot^="navigation-menu-"]
) {
  transition:
    background var(--t-micro),
    color var(--t-micro);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )
  .v-icon {
  transition: transform var(--t-element) var(--enter);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  ):hover
  .v-icon {
  transform: translateY(-1px) rotate(-6deg);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  ):active
  .v-icon {
  transform: scale(0.92);
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  ).-paused::after,
.-paused
  .v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"]::after {
  animation-play-state: paused;
}
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"],
.v-nav__item:where(
    [data-slot="navigation-menu"],
    [data-slot^="navigation-menu-"]
  )[aria-current="page"]
  .v-icon {
  color: var(--v-pink);
}
@keyframes v-breathe {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="navigation-menu"],
  [data-slot^="navigation-menu-"],
  [data-slot="navigation-menu"]::before,
  [data-slot="navigation-menu"]::after,
  [data-slot^="navigation-menu-"]::before,
  [data-slot^="navigation-menu-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="navigation-menu-list"] {
  display: grid;
  gap: 2px;
  list-style: none;
  margin: 0;
  padding: 0;
}
[data-slot="navigation-menu-item"] {
  display: contents;
}
[data-slot="navigation-menu-label"] {
  flex: 1;
  min-width: 0;
}

[data-slot="navigation-menu"] {
  position: relative;
  min-width: 0;
}
[data-slot="navigation-menu"][data-orientation="horizontal"]
  [data-slot="navigation-menu-list"] {
  display: flex;
  flex-wrap: wrap;
}
[data-slot="navigation-menu-content"] {
  min-width: 0;
  max-width: min(520px, calc(100vw - 32px));
  padding: var(--s-4);
  background: var(--popover);
  color: var(--popover-foreground);
  border-radius: var(--r-card-sm);
  box-shadow: var(--shadow-float);
}
[data-slot="navigation-menu-viewport"] {
  position: relative;
  max-width: calc(100vw - 32px);
  overflow: hidden;
}
[data-slot="navigation-menu-link"],
[data-slot="navigation-menu-trigger"] {
  min-width: 0;
  min-height: var(--nav-row);
  height: auto;
  padding-block: var(--s-2);
}
[data-slot="navigation-menu-link"] > svg,
[data-slot="navigation-menu-count"] {
  flex-shrink: 0;
}

/* Nested menus live above dialog surfaces as well as the document. */
[data-slot="navigation-menu-content"],
[data-slot="navigation-menu-viewport"] {
  z-index: var(--z-popover);
}
[data-slot="navigation-menu-viewport"]
  > [data-slot="navigation-menu-content"][data-state="closed"] {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
[data-slot="navigation-menu-viewport"]
  > [data-slot="navigation-menu-content"][data-motion-exiting="true"] {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

[data-slot="navigation-menu-link"],
[data-slot="navigation-menu-trigger"] {
  gap: 12px;
  text-align: start;
  overflow-wrap: anywhere;
}
[data-slot="navigation-menu-content"] [data-slot="navigation-menu-link"] {
  white-space: normal;
  min-width: 0;
}
[data-slot="navigation-menu-link"] .v-item-adornment .v-icon,
[data-slot="navigation-menu-trigger"] .v-item-adornment .v-icon {
  width: 15px;
  height: 15px;
  color: var(--adornment-foreground);
  transform: none;
  transition: none;
}
[data-slot="navigation-menu-trigger"]:is(:hover, [data-state="open"]) {
  background: var(--v-beige);
  color: var(--v-text);
}
[data-slot="navigation-menu-trigger"] > .v-state-chevron .v-icon {
  width: 16px;
  height: 16px;
  transform: none;
  transition: none;
}

/* Standalone navigation uses its surrounding surface; an inverse rail can
   override these local variables without recoloring the icon palette. */
[data-slot="navigation-menu"] {
  --nav-ink: var(--v-text);
  --nav-active-ink: var(--v-text);
  --rail-sel: var(--v-pink-soft);
  --rail-hover: color-mix(in oklab, var(--v-ink) 6%, transparent);
}
[data-slot="navigation-menu-link"] {
  color: var(--nav-ink);
}
[data-slot="navigation-menu-trigger"] {
  color: var(--nav-ink);
}
[data-slot="navigation-menu-link"][aria-current="page"],
[data-slot="navigation-menu-link"][aria-current="page"] > .v-icon {
  color: var(--nav-active-ink);
}
[data-slot="navigation-menu-link"][aria-current="page"]::after {
  background: var(--v-accent-ink);
}
[data-slot="navigation-menu-link"] > .v-item-adornment[data-custom] {
  color: inherit;
}

.v-navigation-example {
  display: grid;
  gap: 24px;
  min-width: 0;
  padding: 12px;
}
.v-navigation-example__result {
  display: grid;
  gap: 8px;
  border-inline-start: 3px solid var(--v-accent-ink);
  padding: 12px 16px;
  background: var(--v-canvas);
  border-radius: 0 12px 12px 0;
}
.v-navigation-example__result p {
  font-size: var(--fs-meta);
  color: var(--v-text-2);
  margin: 0;
}
[data-slot="navigation-menu"][data-appearance]
  [data-slot="navigation-menu-link"],
[data-slot="navigation-menu"][data-appearance]
  [data-slot="navigation-menu-trigger"] {
  min-height: 44px;
  padding: 12px;
  font-size: var(--fs-control);
}
[data-slot="navigation-menu"][data-appearance]
  [data-slot="navigation-menu-link"][aria-current="page"]::after {
  animation: none;
}
[data-slot="navigation-menu"][data-appearance] .v-nav__destination {
  display: grid;
  gap: 4px;
  flex: 1;
  min-width: 0;
}
[data-slot="navigation-menu"][data-appearance] .v-nav__destination > small {
  font-size: 12px;
  line-height: 1.45;
  color: var(--v-text-2);
  font-weight: 400;
}
[data-slot="navigation-menu"][data-appearance="directory"]
  [data-slot="navigation-menu-list"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
[data-slot="navigation-menu"][data-appearance="directory"]
  [data-slot="navigation-menu-item"] {
  display: block;
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--v-edge);
  border-radius: 20px;
  background: var(--v-canvas);
}
.v-nav__directory-heading {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 4px 12px 12px;
  border-bottom: 1px solid var(--v-edge);
  margin-bottom: 8px;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.v-nav__directory-heading small {
  margin-inline-start: auto;
  color: var(--v-text-2);
  font-variant-numeric: tabular-nums;
}
[data-slot="navigation-menu"][data-appearance="shelf"] {
  padding: 16px;
  border: 1px solid var(--v-edge);
  border-radius: 20px;
  background: var(--v-canvas);
  gap: 12px;
}
[data-slot="navigation-menu"][data-appearance="shelf"]
  > div
  > [data-slot="navigation-menu-list"] {
  gap: 12px;
}
[data-slot="navigation-menu"][data-appearance]
  [data-slot="navigation-menu-viewport"] {
  width: 100%;
  max-width: 100%;
  border-radius: 16px;
}
[data-slot="navigation-menu"][data-appearance]
  [data-slot="navigation-menu-content"] {
  max-width: 100%;
  padding: 16px;
  box-shadow: none;
  border: 1px solid var(--v-edge);
  background: var(--v-canvas);
  color: var(--v-text);
}
.v-nav__shelf-content {
  display: grid;
  grid-template-columns: minmax(120px, 0.8fr) minmax(0, 1.2fr);
  gap: 16px;
}
.v-nav__feature {
  display: grid;
  align-content: space-between;
  gap: 24px;
  padding: 20px;
  min-height: 200px;
  border-radius: 12px;
  background: var(--v-pink-soft);
  color: var(--v-text);
}
.v-nav__feature > .v-icon {
  color: var(--v-accent-ink);
  width: 32px;
  height: 32px;
}
.v-nav__feature strong {
  display: block;
  font-size: 20px;
  margin-bottom: 8px;
}
.v-nav__feature p {
  font-size: 13px;
  line-height: 1.5;
  color: var(--v-text-2);
  margin: 0;
}
[data-slot="navigation-menu"][data-appearance="compact"] {
  max-width: 380px;
  gap: 12px;
}
[data-slot="navigation-menu"][data-appearance="compact"]
  [data-slot="navigation-menu-list"] {
  padding: 6px;
  border: 1px solid var(--v-edge);
  border-radius: 16px;
  background: var(--v-beige);
  gap: 4px;
}
[data-slot="navigation-menu"][data-appearance="compact"]
  [data-slot="navigation-menu-content"] {
  padding: 8px;
}
.v-nav__compact-content > p {
  padding: 8px 12px;
  margin: 0;
  font-size: 12px;
  color: var(--v-text-2);
  border-bottom: 1px solid var(--v-edge);
}
@media (max-width: 640px) {
  [data-slot="navigation-menu"][data-appearance="directory"]
    [data-slot="navigation-menu-list"] {
    grid-template-columns: 1fr;
  }
  .v-nav__shelf-content {
    grid-template-columns: 1fr;
  }
  .v-nav__feature {
    min-height: 0;
    grid-template-columns: 32px minmax(0, 1fr);
    gap: 16px;
    padding: 16px;
  }
  [data-slot="navigation-menu"][data-appearance="shelf"] {
    padding: 12px;
  }
  [data-slot="navigation-menu"][data-appearance]
    [data-slot="navigation-menu-content"] {
    padding: 8px;
  }
}

}
